// Uses FD 1 (stdout)
#define STDOUT_FILENO 1
char message[] = "System Call Test\n";
ssize_t count = write(STDOUT_FILENO, message, 17);
if (count < 0) {
    // Handle EFAULT, EINTR, etc.
}


// Syscall: Process Creation (fork)
pid_t pid = fork();
if (pid == 0) {
    // Child: Overwrite process image
    execl("/bin/echo", "echo", "In Child", NULL);
    _exit(1); // Should only happen on error
} else if (pid > 0) {
    // Parent: Wait for child ECF termination
    waitpid(pid, NULL, 0);
}


// Signal Handler Definition (ECF Setup)
void termination_handler(int sig) {
    // Async-safe operations only
    if (sig == SIGTERM) {
        // Clean shutdown logic
        _exit(0);
    }
}

struct sigaction sa;
sa.sa_handler = termination_handler;
sigemptyset(&sa.sa_mask);
sa.sa_flags = 0;
sigaction(SIGTERM, &sa, NULL);


// System Call: Sending a Signal (Interruption)
pid_t target_pid = 12345;
int status = kill(target_pid, SIGKILL);

if (status == 0) {
    // Signal delivery successful
} else {
    // E.g., ESRCH (PID doesn't exist) or EPERM
}


// Blocking Signals Temporarily
sigset_t old_mask, block_mask;
sigemptyset(&block_mask);
sigaddset(&block_mask, SIGINT);

// Block SIGINT
sigprocmask(SIG_BLOCK, &block_mask, &old_mask);

// Critical section execution...

// Restore original mask (unblock SIGINT)
sigprocmask(SIG_SETMASK, &old_mask, NULL);
